preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");
@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: .8rem .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtsf-font-size로 바꿉니다. */
.rtsf {
  --rtsf-bg-fill: transparent;
  --rtsf-blur: none;
  --rtsf-bg-edge: none;
  --rtsf-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtsf-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtsf-font-size: 15px;
  --rtsf-line-height: 1.75;
  --rtsf-para-gap: .8em;
  --rtsf-dialog-weight: 500;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtsf {
  --risu-font-family: var(--rtsf-font-body);
  --FontColorStandard: var(--rtsf-ink);
  --FontColorBold: var(--rtsf-ink);
  --FontColorItalic: var(--rtsf-muted);
  --FontColorItalicBold: var(--rtsf-muted);
  --FontColorQuote1: var(--rtsf-muted);
  --FontColorQuote2: var(--rtsf-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtsf-ink);
  font-family: var(--rtsf-font-body);
  font-size: var(--rtsf-font-size);
  line-height: var(--rtsf-line-height);
}
.rtsf, .rtsf *, .rtsf *::before, .rtsf *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtsf.rtsf { display: block; }
.rtsf__content {
  min-width: 0;
  color: var(--rtsf-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtsf__content .chattext {
  --tw-prose-code: var(--rtsf-ink);
  --tw-prose-pre-code: var(--rtsf-ink);
  --tw-prose-pre-bg: var(--rtsf-tint);
  max-width: none;
  color: var(--rtsf-ink);
  font-size: var(--rtsf-font-size) !important;
  line-height: var(--rtsf-line-height) !important;
}
.rtsf__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtsf-font-size);
  line-height: var(--rtsf-line-height);
}
.rtsf__content p { margin: 0 0 var(--rtsf-para-gap); }
.rtsf__content p:last-child { margin-bottom: 0; }
.rtsf__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtsf-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtsf-ink);
  font-family: var(--rtsf-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtsf__content h1 { font-size: calc(var(--rtsf-font-size) * 1.6); }
.rtsf__content h2 { font-size: calc(var(--rtsf-font-size) * 1.35); }
.rtsf__content h3 { font-size: calc(var(--rtsf-font-size) * 1.15); }
.rtsf__content :is(h4, h5, h6) { font-size: var(--rtsf-font-size); }
.rtsf__content strong { font-weight: 700; }
.rtsf__content em { color: var(--rtsf-muted); }
.rtsf__content mark[risu-mark="quote1"],
.rtsf__content mark[risu-mark="blockquote1"] { color: var(--rtsf-muted); background: transparent; }
.rtsf__content mark[risu-mark="quote2"],
.rtsf__content mark[risu-mark="blockquote2"] {
  color: var(--rtsf-dialog);
  font-weight: var(--rtsf-dialog-weight);
  background: transparent;
}
.rtsf__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtsf-line);
  color: var(--rtsf-muted);
}
.rtsf__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtsf__content li { margin: .25em 0; color: var(--rtsf-ink); }
.rtsf__content li::marker { color: var(--rtsf-muted); }
.rtsf__content a { color: var(--rtsf-accent); text-decoration: underline; }
.rtsf__content hr { border: 0; border-top: 1px solid var(--rtsf-line); margin: 1.5em 0; }
.rtsf__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtsf-ink);
  background: var(--rtsf-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtsf-font-size) * .88);
}
.rtsf__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtsf-ink);
  background: var(--rtsf-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtsf-font-size) * .88);
  line-height: 1.5;
}
.rtsf__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtsf__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtsf__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtsf-ink);
  border-bottom: 1px solid var(--rtsf-line);
  text-align: left;
  vertical-align: top;
}
.rtsf__content th { font-weight: 700; }
.rtsf__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtsf__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtsf-ink) !important;
  background: var(--rtsf-edit-bg) !important;
  border: 1px solid var(--rtsf-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtsf-font-size) !important;
  line-height: var(--rtsf-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtsf__footer {
  --risu-theme-textcolor2: var(--rtsf-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtsf__info, .rtsf__actions { min-width: 0; max-width: 100%; }
.rtsf__info > div, .rtsf__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtsf__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtsf__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtsf__footer button:hover { background: var(--rtsf-tint); }
.rtsf :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtsf-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtsf__portrait { overflow: hidden; background: var(--rtsf-tint); }
.rtsf__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtsf__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtsf-bg-fill);
  -webkit-backdrop-filter: var(--rtsf-blur);
  backdrop-filter: var(--rtsf-blur);
  box-shadow: var(--rtsf-bg-edge);
}

/* 구조: SF */

/* 화면 테두리(베젤) */
.rtsf {
  max-width: 54rem;
  margin: 0 auto;
  padding: clamp(5px, 1.2%, 10px);
  background: var(--rtsf-bezel);
  border-radius: clamp(.5rem, 1.6%, 1rem);
  box-shadow: 0 0 0 1px var(--rtsf-frame), 0 8px 22px rgba(0, 0, 0, .3);
}
.rtsf__screen {
  position: relative;
  padding: .9rem clamp(.9rem, 3vw, 1.6rem) .8rem;
  background:
    repeating-linear-gradient(to bottom, var(--rtsf-scan) 0, var(--rtsf-scan) 1px, transparent 1px, transparent 3px),
    var(--rtsf-panel);
  border-radius: clamp(.3rem, 1%, .6rem);
  box-shadow: inset 0 0 30px var(--rtsf-inner-glow), inset 0 0 0 1px var(--rtsf-frame);
}
/* 모서리 표식: 카드 폭에 맞춰 크기가 바뀝니다 */
.rtsf__screen::before, .rtsf__screen::after {
  content: "";
  position: absolute;
  width: clamp(10px, 3%, 22px);
  aspect-ratio: 1;
  border: 2px solid var(--rtsf-accent);
  pointer-events: none;
}
.rtsf__screen::before { top: 5px; left: 5px; border-right: 0; border-bottom: 0; }
.rtsf__screen::after { bottom: 5px; right: 5px; border-left: 0; border-top: 0; }
.rtsf__bar {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-bottom: .8rem;
  padding-bottom: .5rem;
  border-bottom: 1px solid var(--rtsf-frame);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: .72em;
  letter-spacing: .14em;
  color: var(--rtsf-muted);
}
.rtsf__channel { color: var(--rtsf-accent); font-weight: 600; }
.rtsf__name { color: var(--rtsf-ink); letter-spacing: .06em; }
.rtsf__signal { margin-left: auto; width: 2.2em; height: .55em; background: repeating-linear-gradient(to right, var(--rtsf-accent) 0 3px, transparent 3px 5px); opacity: .8; }
.rtsf__body { display: flex; align-items: flex-start; gap: 1rem; }
.rtsf__portrait {
  position: relative;
  flex: 0 0 auto;
  width: var(--rtsf-portrait-w);
  aspect-ratio: 4 / 5;
  border: 1px solid var(--rtsf-accent);
  box-shadow: 0 0 12px var(--rtsf-inner-glow);
}
.rtsf__portrait::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(to bottom, transparent 0 2px, var(--rtsf-scan-strong) 2px 3px);
  pointer-events: none;
}
.rtsf { --rtsf-portrait-w: clamp(3.6rem, 11%, 6rem); }
.rtsf--user { --rtsf-portrait-w: clamp(2.6rem, 7%, 3.6rem); }
.rtsf--user .rtsf__body { flex-direction: row-reverse; }
.rtsf__content { flex: 1 1 auto; }
.rtsf__content :is(h1, h2, h3) { color: var(--rtsf-accent); }
.rtsf__footer { margin-top: .8rem; padding-top: .5rem; border-top: 1px solid var(--rtsf-frame); font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace; font-size: .78em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtsf {
  --rtsf-blur: blur(16px) saturate(1.25);
  --rtsf-bg-edge: inset 0 0 0 1px rgba(255, 255, 255, .13), inset 0 1px 0 rgba(255, 255, 255, .18);
  --rtsf-bg-fill: linear-gradient(160deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 65%);
  --rtsf-bezel: rgba(10, 14, 18, .35);
  --rtsf-panel: rgba(12, 16, 20, .4);
  --rtsf-frame: rgba(255, 255, 255, .14);
  --rtsf-scan: rgba(255, 255, 255, .025);
  --rtsf-scan-strong: rgba(0, 0, 0, .15);
  --rtsf-inner-glow: rgba(180, 220, 220, .06);
  --rtsf-ink: #e9eef0;
  --rtsf-muted: rgba(225, 232, 235, .66);
  --rtsf-accent: #bcd6d3;
  --rtsf-dialog: #ffffff;
  --rtsf-line: rgba(255, 255, 255, .13);
  --rtsf-tint: rgba(255, 255, 255, .07);
  --rtsf-edit-bg: rgba(10, 11, 15, .5);
}
